<template><div class="app-container ps-page"><h2>知识问答</h2><el-alert v-if="error||stream.error.value" :title="error||stream.error.value" type="error" :closable="false" class="ps-error"/><div class="chat-layout"><ConversationList :selected="current?.id" :refresh-key="refreshKey" @select="selectConversation" @create="create"/><section class="chat-main ps-panel"><div class="ps-toolbar"><strong>{{current?.title||'选择或新建会话'}}</strong><el-button v-if="current" v-hasPermi="['paismart:conversation:list']" link @click="archive">归档会话</el-button><el-button v-if="stream.state.value==='disconnected'||stream.state.value==='failed'" :disabled="!stream.generationId.value" @click="stream.resume()">恢复生成</el-button></div><div class="message-list" aria-live="polite" v-loading="loading"><ChatMessage v-for="message in messages" :key="message.id" :message="message" @reference="openReference"/><ChatMessage v-if="showStream" :message="streamMessage" streaming @reference="openReference"/><el-empty v-if="!messages.length&&!showStream" description="提问后将从有权访问的知识中检索回答"/></div><el-pagination v-if="messageTotal>messageSize" v-model:current-page="messagePage" :page-size="messageSize" :total="messageTotal" layout="total,prev,pager,next" :disabled="generating||loading" @current-change="readMessages(false)"/><p v-if="stream.tools.value.length" class="ps-muted">工具执行：<span v-for="tool in stream.tools.value" :key="tool.name">{{tool.name}}（{{tool.state==='COMPLETE'?'已完成':tool.state==='RUNNING'?'执行中':tool.state}}） </span></p><el-input v-model="draft" type="textarea" :rows="4" maxlength="16000" show-word-limit placeholder="输入问题，Ctrl+Enter 发送" :disabled="generating" @keydown.ctrl.enter.prevent="send" aria-label="问答问题"/><div class="ps-toolbar" style="margin-top:12px"><el-button v-hasPermi="['paismart:chat:send']" type="primary" :disabled="!draft.trim()||generating" :loading="stream.state.value==='connecting'" @click="send">发送问题</el-button><el-button v-if="generating" :disabled="!stream.generationId.value||stream.state.value==='stopping'" @click="stream.stop()">停止生成</el-button><span role="status">{{streamStatus}}</span></div></section><aside class="ps-panel reference-list"><h3>当前回答引用</h3><el-empty v-if="!currentReferences.length" description="回答引用将在这里显示" :image-size="60"/><el-button v-for="(reference,i) in currentReferences" :key="reference.id" class="reference-button" text @click="openReference(reference)">[{{i+1}}] {{reference.title}}<br/>{{reference.page?'第 '+reference.page+' 页':''}}</el-button><p class="ps-muted">引用按生成时的内容版本读取，权限变更后由服务端重新判定。</p></aside></div><ReferencePreview v-model="referenceOpen" :reference="selectedReference"/></div></template>
<script setup lang="ts">
import { computed, onMounted, ref, shallowRef } from 'vue'
import { useRoute } from 'vue-router'
import { conversationAction, conversationMessages, createConversation } from '@/api/paismart/conversations'
import { getActiveGeneration } from '@/api/paismart/chat'
import type { Conversation, Message, Reference } from '@/types/paismart'
import { errorText } from '../composables/usePage'
import { useChatStream } from '../composables/useChatStream'
import ConversationList from './components/ConversationList.vue'
import ChatMessage from './components/ChatMessage.vue'
import ReferencePreview from './components/ReferencePreview.vue'
import '../common.css'
const route=useRoute(),current=shallowRef<Conversation>(),messages=shallowRef<Message[]>([]),draft=ref(''),error=ref(''),loading=ref(false),refreshKey=ref(0),showStream=ref(false),referenceOpen=ref(false),selectedReference=shallowRef<Reference>()
const currentReferences=computed(()=>showStream.value?stream.references.value:([...messages.value].reverse().find(message=>message.role==='assistant')?.references??[]))
const messagePage=ref(1),messageTotal=ref(0),messageSize=100
let serial=0
const stream=useChatStream(()=>{void finished()}),generating=computed(()=>['connecting','generating','stopping'].includes(stream.state.value)),streamMessage=computed<Message>(()=>({id:'stream',role:'assistant',content:stream.text.value,references:stream.references.value,state:streamStatus.value})),streamStatus=computed(()=>({idle:'',connecting:'正在连接',generating:'正在生成',stopping:'正在停止',done:'生成完成',stopped:'已停止',disconnected:'连接中断',failed:'生成未完成'} as Record<string,string>)[stream.state.value])
async function readMessages(tail=true){if(!current.value)return;const id=current.value.id,version=++serial;loading.value=true;error.value='';try{let response=await conversationMessages(id,{pageNum:tail?1:messagePage.value,pageSize:messageSize});if(tail){const last=Math.max(1,Math.ceil(response.total/messageSize));if(last>1)response=await conversationMessages(id,{pageNum:last,pageSize:messageSize});if(version===serial)messagePage.value=last}if(version===serial){messages.value=response.rows;messageTotal.value=response.total}}catch(e){if(version===serial)error.value=errorText(e)}finally{if(version===serial)loading.value=false}}
async function selectConversation(row:Conversation){if(generating.value){error.value='请先停止当前生成，再切换会话';return}current.value=row;messages.value=[];stream.references.value=[];stream.tools.value=[];showStream.value=false;await readMessages()}
async function create(){error.value='';try{const row=(await createConversation('新会话')).data;refreshKey.value++;await selectConversation(row)}catch(e){error.value=errorText(e)}}
async function send(){if(!draft.value.trim()||generating.value)return;error.value='';if(!current.value)await create();if(!current.value)return;const question=draft.value.trim();messages.value=[...messages.value,{id:crypto.randomUUID(),role:'user',content:question}];showStream.value=true;await stream.send(current.value.id,question);if(stream.state.value!=='failed')draft.value=''}
async function finished(){refreshKey.value++;if(!current.value)return;await readMessages();if(!error.value)showStream.value=false}
async function archive(){if(!current.value||generating.value)return;try{await conversationAction(current.value,'archive');current.value=undefined;messages.value=[];showStream.value=false;refreshKey.value++}catch(e){error.value=errorText(e)}}
function openReference(reference:Reference){selectedReference.value=reference;referenceOpen.value=true}
onMounted(async()=>{try{const active=(await getActiveGeneration()).data;if(active){current.value={id:active.conversationId,title:'恢复中的会话',rowVersion:0,archived:false};showStream.value=true;await stream.resume(active.generationId)}else if(typeof route.query.conversationId==='string')await selectConversation({id:route.query.conversationId,title:'历史会话',rowVersion:0,archived:false})}catch(e){error.value=errorText(e)}})
</script>
<style scoped>.chat-layout{display:grid;grid-template-columns:250px minmax(320px,1fr) 250px;gap:16px}.chat-main{min-width:0}.message-list{min-height:300px;max-height:60vh;overflow:auto}.reference-button{width:100%;height:auto;justify-content:flex-start;text-align:left;margin:0 0 12px;white-space:normal}@media(max-width:1250px){.chat-layout{grid-template-columns:230px minmax(0,1fr)}.reference-list{grid-column:1/-1}}@media(max-width:760px){.chat-layout{grid-template-columns:1fr}}</style>
